<?php
require_once __DIR__.'/../includes/config.php';
require_once __DIR__.'/../includes/session.php';
if(session_status()===PHP_SESSION_NONE)session_start();
if(empty($_SESSION['rider_id'])){header('Location:rider-login.php');exit;}
$rid=(int)$_SESSION['rider_id'];
function rh($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$rows=[];
$sql="SELECT rd.id,rd.order_id,rd.status AS delivery_status,rd.assigned_at,rd.accepted_at,rd.picked_up_at,rd.delivered_at,o.order_number,o.total,o.order_status,o.created_at,r.name AS restaurant_name,u.full_name AS customer_name,u.phone AS customer_phone FROM rider_deliveries rd JOIN orders o ON o.id=rd.order_id LEFT JOIN restaurants r ON r.id=o.restaurant_id LEFT JOIN users u ON u.id=o.user_id WHERE rd.rider_id=? ORDER BY rd.id DESC";
$st=$conn->prepare($sql);if($st){$st->bind_param('i',$rid);$st->execute();$res=$st->get_result();while($x=$res->fetch_assoc())$rows[]=$x;$st->close();}
$active=[];$history=[];foreach($rows as $x){if(in_array(strtolower((string)$x['delivery_status']),['accepted','picked_up','on_the_way','out_for_delivery'],true))$active[]=$x;else$history[]=$x;}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Deliveries | Humsafar</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><style>*{box-sizing:border-box}body{margin:0;background:#f7f7f9;font:14px Segoe UI,Arial;color:#222}.page{margin-left:223px;padding:32px;max-width:1250px}.head h1{margin:0;font-size:32px}.head p{color:#777}.card{background:#fff;border:1px solid #eee;border-radius:16px;padding:20px;margin:18px 0;box-shadow:0 6px 20px #00000008}.row{display:flex;justify-content:space-between;gap:15px;align-items:center}.title{font-size:18px;font-weight:800}.meta{color:#777;margin-top:5px}.badge{padding:7px 11px;border-radius:20px;background:#e9f8ef;color:#187c43;font-weight:800;font-size:12px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:15px}.box{background:#fafafa;border-radius:10px;padding:12px}.box small{color:#888;display:block}.box b{display:block;margin-top:4px}.empty{text-align:center;color:#888;padding:45px}.section{font-size:20px;font-weight:850;margin-top:28px}@media(max-width:900px){.page{margin-left:0;padding:20px}.grid{grid-template-columns:1fr 1fr}}@media(max-width:600px){.grid{grid-template-columns:1fr}.row{align-items:flex-start;flex-direction:column}}</style></head><body><?php include __DIR__.'/rider-sidebar.php'; ?><main class="page"><div class="head"><h1>My Deliveries</h1><p>Track your accepted, active and completed deliveries.</p></div><div class="section">Active Deliveries</div><?php if(!$active):?><div class="card empty">No active deliveries right now.</div><?php else:foreach($active as $x):?><div class="card"><div class="row"><div><div class="title">Order #<?=rh($x['order_number']?:$x['order_id'])?></div><div class="meta"><i class="fa-solid fa-store"></i> <?=rh($x['restaurant_name']?:'Restaurant')?></div></div><span class="badge"><?=rh(ucwords(str_replace('_',' ',$x['delivery_status'])))?></span></div><div class="grid"><div class="box"><small>Customer</small><b><?=rh($x['customer_name']?:'Customer')?></b></div><div class="box"><small>Phone</small><b><?=rh($x['customer_phone']?:'—')?></b></div><div class="box"><small>Order Total</small><b>Rs <?=number_format((float)$x['total'],0)?></b></div><div class="box"><small>Accepted</small><b><?=rh($x['accepted_at']?date('d M, h:i A',strtotime($x['accepted_at'])):'—')?></b></div></div></div><?php endforeach;endif;?><div class="section">Delivery History</div><?php if(!$history):?><div class="card empty">No delivery history yet.</div><?php else:foreach($history as $x):?><div class="card"><div class="row"><div><div class="title">Order #<?=rh($x['order_number']?:$x['order_id'])?></div><div class="meta"><?=rh($x['restaurant_name']?:'Restaurant')?> · <?=rh($x['customer_name']?:'Customer')?></div></div><span class="badge"><?=rh(ucwords(str_replace('_',' ',$x['delivery_status'])))?></span></div><div class="meta" style="margin-top:12px">Delivered: <?=rh($x['delivered_at']?date('d M Y, h:i A',strtotime($x['delivered_at'])):'—')?> · Rs <?=number_format((float)$x['total'],0)?></div></div><?php endforeach;endif;?></main></body></html>